11→      expect(result.exitCode).toBe(0);
12→    });
13→
14→    it("returns stderr on command failure", async () => {
15→      const result = await runner.run("ls", ["/nonexistent-path-12345"]);
16→      expect(result.exitCode).not.toBe(0);
17→      expect(result.stderr).toBeTruthy();
18→    });
19→
20→    it("times out long-running commands", async () => {
21→      await expect(
22→        runner.run("sleep", ["10"], { timeoutMs: 100 })
23→      ).rejects.toThrow("timed out");
24→    });
25→  });
26→
27→  describe("safety guards", () => {
28→    it("blocks dangerous commands", async () => {
29→      await expect(runner.run("rm", ["-rf", "/"])).rejects.toThrow(
30→        "is not allowed"
31→      );
32→    });
33→
34→    it("blocks reboot commands", async () => {
35→      await expect(runner.run("reboot", [])).rejects.toThrow("is not allowed");
36→    });
37→
38→    it("blocks shutdown commands", async () => {
39→      await expect(runner.run("shutdown", [])).rejects.toThrow("is not allowed");
40→    });
41→
42→    it("blocks su commands", async () => {
43→      await expect(runner.run("su", ["-c", "id"])).rejects.toThrow("is not allowed");
44→    });
45→
46→    it("blocks sudo commands", async () => {
47→      await expect(runner.run("sudo", ["rm", "-rf", "/"])).rejects.toThrow("is not allowed");
48→    });
49→
50→    it("blocks halt commands", async () => {
51→      await expect(runner.run("halt", [])).rejects.toThrow("is not allowed");
52→    });
53→
54→    it("blocks poweroff commands", async () => {
55→      await expect(runner.run("poweroff", [])).rejects.toThrow("is not allowed");
56→    });
57→
58→    it("blocks format commands", async () => {
59→      await expect(runner.run("format", ["/dev/sda"])).rejects.toThrow("is not allowed");
60→    });
61→  });
62→
63→  describe("runAdb", () => {
64→    it("uses environment service to resolve adb path", async () => {
65→      const mockEnv = {
66→        getAdbPath: vi.fn().mockResolvedValue("/custom/path/adb"),
67→      };
